    const current = queue.shift();
    if (current === to) return true;
    for (const edge of edges) {
      if (edge.from === current && edge.to === to) return true;
      if (edge.from === current && edge.to !== to) queue.push(edge.to);
      if (edge.to === current && edge.from !== to) queue.push(edge.from);
    }
  }
  return false;
};

